    /// <summary>Reads sc for a code point.</summary>
    /// <param name="u">The code point.</param>
    /// <returns>The encoded value, or the default outside Unicode.</returns>
    let sc (u: uint32) : byte =
        match u < 0x110000u with
        | false -> 2uy
        | true ->
            let block = int scIndex[int (u >>> scShift)]
            scValues[block * 64 + int (u &&& 63u)]

